import py3_kit


def test_slide():
    slide_distance = py3_kit.slide.get_double_image_slide_distance(
        "data:image/png;base64,",
        "data:image/png;base64,",
        254,
        "slide",
    )
    print(slide_distance)

    bessel_function_slide_points = py3_kit.slide.get_slide_points_by_bessel_function(slide_distance)
    ghost_cursor_slide_points = py3_kit.slide.get_slide_points_by_ghost_cursor(slide_distance)
    print(bessel_function_slide_points)
    print(ghost_cursor_slide_points)

    slide_points = py3_kit.slide.get_slide_points(slide_distance)
    print(slide_points)

    slide_trajectories = py3_kit.slide.get_slide_trajectories_by_slide_points(
        slide_points,
        time_interval=(5, 10)
    )
    print(slide_trajectories)

    slide_trajectories = py3_kit.slide.get_slide_trajectories_by_resources(slide_distance)
    print(slide_trajectories)

    format_slide_trajectories = py3_kit.slide.get_format_slide_trajectories(slide_trajectories, False, False, True,
                                                                            False)
    print(format_slide_trajectories)

    slide_js = py3_kit.slide.get_slide_js(
        "#captcha_modal > div > div.captcha_footer > div > img",
        format_slide_trajectories
    )
    print(slide_js)

    py3_kit.slide.plot_slide_trajectories(slide_trajectories, show=True)


if __name__ == '__main__':
    test_slide()
